#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }

    vector<vector<char>> seen(h, vector<char>(w, 0));
    vector<pair<int, int>> layer;
    for (int x = 0; x < h; x++) {
        for (int y = 0; y < w; y++) {
            if (grid[x][y] == '1') {
                seen[x][y] = 1;
                layer.push_back({x, y});
            }
        }
    }
    if (layer.empty() || (long long)layer.size() == h * w) {
        cout << -1 << "\n";
    } else {
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        long long steps = -1;
        while (!layer.empty()) {
            vector<pair<int, int>> next;
            for (const auto& cell : layer) {
                for (int d = 0; d < 4; d++) {
                    int a = cell.first + dx[d], b = cell.second + dy[d];
                    if (a >= 0 && a < h && b >= 0 && b < w && !seen[a][b]) {
                        seen[a][b] = 1;
                        next.push_back({a, b});
                    }
                }
            }
            layer = next;
            steps++;
        }
        cout << steps << "\n";
    }

    return 0;
}

