import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        String[] grid = new String[(int) h];
        for (int i = 0; i < grid.length; i++) {
            grid[i] = next();
        }

        int rowsCount = (int) h, colsCount = (int) w;
        boolean[][] seen = new boolean[rowsCount][colsCount];
        List<int[]> layer = new ArrayList<>();
        for (int x = 0; x < rowsCount; x++) {
            for (int y = 0; y < colsCount; y++) {
                if (grid[x].charAt(y) == '1') {
                    seen[x][y] = true;
                    layer.add(new int[] {x, y});
                }
            }
        }
        if (layer.isEmpty() || layer.size() == rowsCount * colsCount) {
            System.out.println(-1);
        } else {
            int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
            long steps = -1;
            while (!layer.isEmpty()) {
                List<int[]> next = new ArrayList<>();
                for (int[] cell : layer) {
                    for (int d = 0; d < 4; d++) {
                        int a = cell[0] + dx[d], b = cell[1] + dy[d];
                        if (a >= 0 && a < rowsCount && b >= 0 && b < colsCount && !seen[a][b]) {
                            seen[a][b] = true;
                            next.add(new int[] {a, b});
                        }
                    }
                }
                layer = next;
                steps++;
            }
            System.out.println(steps);
        }
    }
}
